static unsigned int find_properties(unsigned int codepoint)
{
    size_t low = 0U;
    size_t high = sizeof(mini_unicode_ranges) / sizeof(mini_unicode_ranges[0]);

    while (low < high) {
        size_t mid = low + (high - low) / 2U;
        const struct mini_unicode_range *range = &mini_unicode_ranges[mid];

        if (codepoint < range->first) {
            high = mid;
        } else if (codepoint > range->last) {
            low = mid + 1U;
        } else {
            return range->properties;
        }
    }
    return 0U;
}

static unsigned int map_codepoint(const struct mini_unicode_map *table,
                                  size_t count, unsigned int codepoint)
{
    size_t low = 0U;
    size_t high = count;

    while (low < high) {
        size_t mid = low + (high - low) / 2U;

        if (codepoint < table[mid].from) {
            high = mid;
        } else if (codepoint > table[mid].from) {
            low = mid + 1U;
        } else {
            return table[mid].to;
        }
    }
    return codepoint;
}

int __mini_unicode_has(unsigned int codepoint, unsigned int property)
{
    if (codepoint > 0x10ffffU ||
        (codepoint >= 0xd800U && codepoint <= 0xdfffU)) {
        return 0;
    }
    return (find_properties(codepoint) & property) != 0U;
}

unsigned int __mini_unicode_tolower(unsigned int codepoint)
{
    if (codepoint > 0x10ffffU ||
        (codepoint >= 0xd800U && codepoint <= 0xdfffU)) {
        return codepoint;
    }
    return map_codepoint(mini_unicode_lower,
                         sizeof(mini_unicode_lower) / sizeof(mini_unicode_lower[0]),
                         codepoint);
}

unsigned int __mini_unicode_toupper(unsigned int codepoint)
{
    if (codepoint > 0x10ffffU ||
        (codepoint >= 0xd800U && codepoint <= 0xdfffU)) {
        return codepoint;
    }
    return map_codepoint(mini_unicode_upper,
                         sizeof(mini_unicode_upper) / sizeof(mini_unicode_upper[0]),
                         codepoint);
}
